import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>一张 PNG 截图可能比同样图片的 JPG 重十倍。转换不到一分钟，结果发送、上传、存储都容易得多。</p>\n<p>唯一需要留意的是透明背景。JPG 存不了透明像素，转换前需要给它们选一个填充颜色。</p>\n<p>这篇指南按步骤走，让你第一次转换就干净利落。</p>\n<h2 id=\"before-you-start\">开始之前：检查有没有透明背景</h2>\n<p>打开 PNG，看它的背景。照片或截图没有透明，转换时不用想填充颜色的事。</p>\n<p>标志、图标或产品抠图可能有透明。透明区域需要一个底色，开始之前就该决定用哪个。</p>\n<p>白色适合大多数目的地。文档、网页、表格通常是白底，白底填充看起来很自然。</p>\n<p>每张文件最大接受 25MB。视网膜截图和大型产品渲染图都在这个范围内，不用任何准备。</p>\n<h2 id=\"step-1-open-tool\">第 1 步：打开 PNG 转 JPG 工具</h2>\n<p>在浏览器里打开<a href=\"/zh/png-zhuan-jpg/\">PNG 转 JPG 工具</a>。Windows、Mac、Linux、ChromeOS、安卓、iOS 上都能用，不用安装。</p>\n<p>你会看到上传区域、底色选择器和画质滑块。整个任务就是这三个控件。</p>\n<p>不用注册账号，什么都不上传。转换在你的设备上进行，私人面板和文档的截图都很看重这一点。</p>\n<p>手机上也一样，在移动浏览器里用。点上传区域，从相册里选 PNG。</p>\n<h2 id=\"step-2-upload\">第 2 步：上传 PNG 文件</h2>\n<p>把 PNG 文件拖到上传区域，或者点一下打开文件选择器。一次可以选很多文件做批量。</p>\n<p>每张文件都会显示成一张卡片，带缩略图、尺寸和大小。快速扫一遍，确认传的是正确的文件，没有多余的混进来。</p>\n<p>也可以用 Ctrl+V 直接从剪贴板粘贴截图。这是转换刚截好的图最快的方法。</p>\n<p>隔行扫描的 PNG 也支持，包括 Adam7 格式。解码器正常读取，不用先转换它们。</p>\n<h2 id=\"step-3-matte-colour\">第 3 步：选择底色</h2>\n<p>点底色选择器，给透明区域选填充色。白色是默认，适合大多数用途。</p>\n<p>图片要放在深色背景上，选深炭色；或者输入十六进制代码，精确匹配特定网站的品牌色。</p>\n<p>PNG 没有透明时，这个设置不起作用。照片和截图无论选什么颜色，都原样通过。</p>\n<p>转换后检查一张标志卡片，看看底色效果。颜色错了马上就能看出来，改了再转一次就行。</p>\n<h2 id=\"step-4-quality\">第 4 步：设置画质滑块</h2>\n<p>画质滑块范围 20% 到 100%。带文字的截图用 85% 到 90%，字母保持清晰。</p>\n<p>存成 PNG 的照片用 80% 到 85% 是最佳区间。照片看起来干净，文件大幅缩小。</p>\n<p>只有大小限制逼着你时才降低画质。从 90% 降到 80%，文件常常小一半，肉眼几乎看不出变化。</p>\n<p>截图别低于 70%。小字在低画质下很快变模糊，模糊的截图比大截图更糟。</p>\n<h2 id=\"step-5-convert-preview\">第 5 步：转换并预览结果</h2>\n<p>点“转换”按钮。每张文件独立转换，进度可以逐张卡片看到。</p>\n<p>每张卡片显示新 JPG 的大小和原来 PNG 的大小。好的转换能让截图缩小 80% 以上。</p>\n<p>点卡片上的“对比”，并排检查结果。拖动分割线，放大文字、边缘和阴影看。</p>\n<p>文字发软时，把画质调高五点再转一次。原 PNG 还留在队列里，不用重新上传。</p>\n<h2 id=\"step-6-download\">第 6 步：下载 JPG 文件</h2>\n<p>点单张卡片上的“下载”，保存一张 JPG。文件名保留原名，换成 .jpg 后缀。</p>\n<p>批量时点“全部下载”，拿到一个装着所有转好 JPG 的 ZIP 包。ZIP 名字能看出里面是转换好的文件。</p>\n<p>使用之前检查一次下载好的文件。在看图软件里打开一张 JPG，确认样子没问题，确认它能在需要的地方打开。</p>\n<p>原 PNG 也留着。JPG 永远变不回完美的 PNG，原文件就是你的后路。</p>\n<ol>\n<li>打开 PNG 转 JPG 工具，上传 PNG 文件。</li>\n<li>给透明区域选一个底色。</li>\n<li>画质滑块设到 85% 或更高。</li>\n<li>转换后用“对比”预览，再下载 JPG。</li>\n</ol>\n<h2 id=\"converting-screenshots\">正确转换截图的方法</h2>\n<p>截图是最常见的 PNG 转 JPG 任务。Mac 和 Windows 都把截图存成 PNG，那些文件比实际需要的大得多。</p>\n<p>用 Ctrl+V 直接粘贴截图，流程最快。截好图、粘贴进转换器，几秒后下载 JPG。</p>\n<p>截图的画质保持在 85% 或更高。菜单、按钮、正文都需要这个画质才能保持可读。</p>\n<p>截图必须像素级完美时，比如法律证据，考虑用 WebP。它在小尺寸下比 JPG 更能保留文字。</p>\n<h2 id=\"converting-a-batch\">批量转换截图</h2>\n<p>在文件选择器里一次选最多 25 张截图。它们一起进入队列，一次点击全部转换。</p>\n<p>整批用同样的底色和画质。截图属于同一文档或演示时，一致性很重要。</p>\n<p>批量运行时留意错误标记。一张损坏的文件只会显示警告，不会打断其余文件，好的文件照样完成。</p>\n<p>批量打成 ZIP 下载，解压到新文件夹。转好的 JPG 和原 PNG 混在一个文件夹里，以后会搞混。</p>\n<h2 id=\"fixing-problems\">常见问题怎么解决</h2>\n<p>透明标志出现黑框，说明底色是黑色或没设。改成白色或页面颜色，再转一次。</p>\n<p>文字看起来模糊，说明画质太低。把滑块调到 90%，用原 PNG 再转一次。</p>\n<p>JPG 只比 PNG 小一点，图片很可能是简单图形。PNG 本来就把纯色压得很好，转换省不了多少。</p>\n<p>文件转失败，检查它是不是真正的 PNG。名为 .png、实际却是 WebP 的文件会让解码器糊涂，改对名字就能解决。</p>\n<h2 id=\"mobile-tips\">手机与平板小技巧</h2>\n<p>手机上点上传区域，从相册里选 PNG。手机上保存的截图和桌面上的转换方式一样。</p>\n<p>手机上的批量保持小一点，大 PNG 在移动处理器上编码很花时间。一次十个文件很舒服。</p>\n<p>下载的文件在手机的“下载”文件夹里。iPhone 去“文件”应用里找，安卓去文件管理器里找。</p>\n<p>大批量截图用电脑。更快的处理器、更大的屏幕，二十五张文件管理起来容易得多。</p>\n<h2 id=\"mac-screenshots\">转换 Mac 截图</h2>\n<p>Mac 截图默认存成 PNG，而且很大。一张视网膜截图可能 5MB，同样图片的 JPG 只有 500KB，肉眼看不出差别。</p>\n<p>用 Shift、Command、4 截好图，再把文件拖进转换器。PNG 几秒就转成 JPG，结果马上能分享。</p>\n<p>Mac 截图的画质保持在 85% 或更高。视网膜文字保持清晰，文件缩小 80% 以上。</p>\n<p>截图必须像素级完美时，比如设计评审，留着 PNG。文件大一点值得，因为每个像素都很重要。</p>\n<p>经常截屏的话，在终端里把 Mac 截图格式改成 JPG。一条命令能让以后每张截图都是 JPG，彻底去掉转换这一步。</p>\n<h2 id=\"windows-screenshots\">转换 Windows 截图</h2>\n<p>Windows 截图也存成 PNG，不管是用 Print Screen 还是截图工具。那些文件很大，转成 JPG 能省下实实在在的空间。</p>\n<p>用 Ctrl+V 把截图直接粘贴进转换器。剪贴板图片马上加载，几秒后下载 JPG，不用摆弄文件。</p>\n<p>截图工具的截图先保存，再转换文件。截图工具默认保存 PNG，转换器处理剩下的事。</p>\n<p>Windows 截图的画质保持在 85%。菜单、任务栏、对话框都保持可读，文件只有 PNG 的零头。</p>\n<p>整张桌面的截图带照片壁纸时，省得特别明显。壁纸存成 JPG 压得很好，PNG 却要精确存储它的每个像素。</p>\n<h2 id=\"phone-screenshots\">转换手机截图</h2>\n<p>iPhone 和安卓的手机截图都存成 PNG，而且堆得很快。一部手机上一百张截图，光 PNG 文件就能浪费 1GB。</p>\n<p>转换需要留着的截图，删掉其余的。大多数截图是临时的，全部留着是白白浪费存储。</p>\n<p>必须留着的截图，比如收据或确认信息，转 85% 画质的 JPG。文字保持可读，文件小得多。</p>\n<p>转换后直接从手机分享 JPG。上传更快、移动数据用得更少，对方用什么设备都能打开。</p>\n<p>批量转换后检查手机存储。腾出的空间常常让人惊讶，手机有了喘息的空间，运行也更好。</p>\n<h2 id=\"design-mockups\">转换设计稿</h2>\n<p>设计稿常常导出成 PNG，因为这种格式让文字和形状保持锐利。那些文件很大，转成 JPG 后分享给客户更容易。</p>\n<p>发给客户评审的设计稿，转 90% 画质的 JPG。设计保持清晰，文件发邮件很容易，客户哪里都能打开。</p>\n<p>客户要加标注的设计稿，留着 PNG。无损格式经得起标注回合，不会退化，JPG 每保存一次就软一点。</p>\n<p>转换前把设计稿按显示尺寸的两倍导出。更大的源头产出更锐利的 JPG，因为编码器有更多细节可用。</p>\n<p>转换后把 PNG 原稿留在项目文件夹里。客户要求改动时，原稿已经准备好了，JPG 只是交付副本。</p>\n<h2 id=\"images-for-presentation\">给演示文稿转换图片</h2>\n<p>演示图片要锐利、体积也要合理。幻灯片里的 PNG 截图看起来清晰，JPG 照片则能防止演示文件变得巨大。</p>\n<p>幻灯片用的截图转 90% 画质的 JPG。文字在投影仪上保持可读，文件也小到能让演示保持可控。</p>\n<p>幻灯片整页照片用 85% 的 JPG。照片看起来干净，幻灯片加载快，观众看到的是图片，而不是像素。</p>\n<p>转换后检查演示总大小。超过 50MB 的演示可能发不出去、传不上去，转换图片常常就是解决办法。</p>\n<p>演讲前在投影仪上测试演示。笔记本上看起来锐利的幻灯片，投影出来可能发软，提前测试能及早发现问题。</p>\n<h2 id=\"images-for-whatsapp-group\">给 WhatsApp 群组转换图片</h2>\n<p>WhatsApp 会自动压缩图片，发到群组的 PNG 截图反正会变成小 JPG。自己先转换，能控制画质。</p>\n<p>发送前把截图转成 85% 画质的 JPG。文字保持可读，文件发送快，WhatsApp 压缩也有个好的起点。</p>\n<p>图片必须保持清晰时，比如付款确认，改以文档形式发送。文档附件完全跳过 WhatsApp 的压缩。</p>\n<p>发送后检查图片。在聊天里打开它，确认文字可读，群聊里一张模糊的截图帮不了任何人。</p>\n<p>发送后把原 PNG 留在手机上。有人要求更清晰的版本时，PNG 已经准备好了，不用重新截图。</p>\n<p>整个流程就是这样：上传、选底色、设画质、下载。想了解背景，请读<a href=\"/zh/blog/png-zhuan-jpg-wanquan-zhinan/\">PNG 转 JPG 完全指南</a>；体积取舍请看<a href=\"/zh/blog/png-zhuan-jpg-wenjian-daxiao-yu-huazhi/\">PNG 转 JPG：体积节省与画质取舍</a>。目的地是网站时，<a href=\"/zh/png-zhuan-webp/\">PNG 转 WebP 工具</a>能在缩小文件的同时保留透明。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"透明的 PNG 该选什么底色？","answer":"匹配 JPG 会出现位置的背景。白色适合大多数文档、网页和表格。深炭色适合深色设计，十六进制代码能精确匹配特定品牌色。使用前，先在目标背景上检查转好的标志。"},{"question":"PNG 截图转 JPG 会糊掉文字吗？","answer":"画质保持在 85% 或更高就不会。小字最先受 JPG 压缩影响，截图用低设置要避免。下载前用“对比”查看器放大文字检查，字母发软就把画质调高。"},{"question":"一次能转换多少张 PNG 文件？","answer":"一次能转换一批 25 张 PNG 截图，打成一个 ZIP 下载。每张独立转换，一张坏图不会拖垮其余文件。文件更多时，分几次跑。"},{"question":"为什么转好的 JPG 比原 PNG 还大？","answer":"极小、简单的图标会出现这种情况，JPG 增加了 PNG 不需要的额外开销。一张 20KB 的扁平单色图标转成 JPG 可能多出几 KB。简单图形留着 PNG 就好，JPG 只在照片和截图这类细节图片上省空间。"},{"question":"PNG 转 JPG 会去掉背景吗？","answer":"不会，它会用你选的底色填充透明背景。结果是一张实心背景的 JPG，不是透明的。想要正确去掉背景，用背景移除工具，把结果存成 PNG。"},{"question":"转换后能改底色吗？","answer":"可以。选个新底色，用原 PNG 再转一次，原文件还留在队列里，不用重新上传。下载前用“对比”检查新结果，底色是整个转换里最显眼的设置。"}];
